import React, { useEffect, useState } from "react";
import axios from "axios";

function AdminPanel({
  candidateForm,
  setCandidateForm,
  onSave,
  editId,
  setEditId,
  onDelete,
  candidates,
  theme,
}) {
  // ================= STATES =================
  const [codes, setCodes] = useState([]);
  const [stats, setStats] = useState({
    totalVoterCodes: 0,
    usedCodes: 0,
    totalVotes: 0,
    turnout: 0,
  });

  const positions = ["President", "Vice President", "Secretary", "Treasurer", "Auditor", "Other"];
  const yearLevels = ["1st Year", "2nd Year", "3rd Year", "4th Year"];
  const blocks = ["Block 1", "Block 2", "Block 3"];

  // ================= FETCH VOTER CODES =================
  const fetchCodes = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get("http://localhost:5000/api/admin/codes", {
        headers: { Authorization: `Bearer ${token}` },
      });
      setCodes(res.data);
    } catch (error) {
      console.error("Failed to fetch voter codes:", error);
    }
  };

  // ================= FETCH ADMIN STATS =================
  const fetchStats = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get("http://localhost:5000/api/admin/stats", {
        headers: { Authorization: `Bearer ${token}` },
      });
      setStats(res.data);
    } catch (error) {
      console.error("Failed to fetch admin stats:", error);
    }
  };

  // ================= FETCH DATA ON MOUNT =================
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => {
    fetchCodes();
    fetchStats();
  }, []);

  // ================= GENERATE VOTER CODES =================
  const generateCodes = async () => {
    const amount = prompt("How many voter codes do you want to generate?");
    if (!amount || isNaN(amount)) {
      alert("Please enter a valid number.");
      return;
    }
    try {
      const token = localStorage.getItem("token");
      await axios.post(
        "http://localhost:5000/api/admin/generate-codes",
        { amount: Number(amount) },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchCodes();
      fetchStats();
      alert(`${amount} voter codes generated successfully!`);
    } catch (error) {
      console.error(error);
      alert("Failed to generate voter codes");
    }
  };

  // ================= DELETE VOTER CODE =================
  const deleteCode = async (id) => {
    if (!window.confirm("Delete this voter code?")) return;
    try {
      const token = localStorage.getItem("token");
      await axios.delete(`http://localhost:5000/api/admin/codes/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      fetchCodes();
      fetchStats();
    } catch (error) {
      alert("Failed to delete code");
    }
  };

  // ================= RESET ELECTION =================
  const resetElection = async () => {
    if (!window.confirm("Reset entire election? All votes will be deleted.")) return;
    try {
      const token = localStorage.getItem("token");
      await axios.post(
        "http://localhost:5000/api/admin/reset-election",
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchCodes();
      fetchStats();
      alert("Election reset successful");
    } catch (error) {
      alert("Failed to reset election");
    }
  };

  // Cancel editing
  const handleCancelEdit = () => {
    setCandidateForm({
      firstName: "",
      lastName: "",
      candidacy: "",
      partylist: "",
      yearLevel: "",
      block: "",
      description: "",
      image: null,
    });
    setEditId(null);
  };

  // Populate form for editing
  const handleEditClick = (c) => {
    setEditId(c._id);
    setCandidateForm({
      firstName: c.firstName,
      lastName: c.lastName,
      candidacy: c.candidacy,
      partylist: c.partylist || "",
      yearLevel: c.yearLevel || "",
      block: c.block || "",
      description: c.description || "",
      image: null,
    });
  };

  return (
    <div
      style={{
        padding: 20,
        borderRadius: 10,
        backgroundColor: theme.card,
        boxShadow: darkModeShadow(theme),
        display: "flex",
        flexDirection: "column",
        gap: 20,
        marginTop: 20,
      }}
    >
      {/* ================= ADMIN STATS ================= */}
      <h3 style={{ color: theme.text }}>Election Statistics</h3>
      <div style={{ display: "flex", gap: 20 }}>
        <div style={statCard(theme)}>
          <h4>Total Codes</h4>
          <p>{stats.totalVoterCodes}</p>
        </div>
        <div style={statCard(theme)}>
          <h4>Votes Cast</h4>
          <p>{stats.totalVotes}</p>
        </div>
        <div style={statCard(theme)}>
          <h4>Turnout</h4>
          <p>{stats.turnout}%</p>
        </div>
      </div>

      <button onClick={resetElection} style={resetButtonStyle}>
        Reset Election
      </button>

      {/* ================= CANDIDATE FORM ================= */}
      <h3 style={{ color: theme.text }}>{editId ? "✏️ Edit Candidate" : "Add Candidate"}</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          onSave();
        }}
        style={{ display: "flex", flexDirection: "column", gap: 10 }}
      >
        <input
          type="text"
          placeholder="First Name"
          value={candidateForm.firstName}
          onChange={(e) => setCandidateForm({ ...candidateForm, firstName: e.target.value })}
          style={inputStyle(theme)}
          required
        />
        <input
          type="text"
          placeholder="Last Name"
          value={candidateForm.lastName}
          onChange={(e) => setCandidateForm({ ...candidateForm, lastName: e.target.value })}
          style={inputStyle(theme)}
          required
        />
        <select
          value={candidateForm.candidacy}
          onChange={(e) => setCandidateForm({ ...candidateForm, candidacy: e.target.value })}
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Candidacy Position</option>
          {positions.map((pos) => (
            <option key={pos} value={pos}>{pos}</option>
          ))}
        </select>
        <select
          value={candidateForm.yearLevel || ""}
          onChange={(e) => setCandidateForm({ ...candidateForm, yearLevel: e.target.value })}
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Year Level</option>
          {yearLevels.map((year) => (
            <option key={year} value={year}>{year}</option>
          ))}
        </select>
        <select
          value={candidateForm.block || ""}
          onChange={(e) => setCandidateForm({ ...candidateForm, block: e.target.value })}
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Block</option>
          {blocks.map((block) => (
            <option key={block} value={block}>{block}</option>
          ))}
        </select>
        <input
          type="text"
          placeholder="Partylist"
          value={candidateForm.partylist || ""}
          onChange={(e) => setCandidateForm({ ...candidateForm, partylist: e.target.value })}
          style={inputStyle(theme)}
        />
        <textarea
          placeholder="Description"
          value={candidateForm.description || ""}
          onChange={(e) => setCandidateForm({ ...candidateForm, description: e.target.value })}
          style={{ ...inputStyle(theme), minHeight: 60 }}
        />
        <input
          type="file"
          onChange={(e) => setCandidateForm({ ...candidateForm, image: e.target.files[0] })}
        />
        <div style={{ display: "flex", gap: 10 }}>
          <button type="submit" style={buttonStyle(theme)}>
            {editId ? "Save Changes" : "Add Candidate"}
          </button>
          {editId && (
            <button type="button" onClick={handleCancelEdit} style={cancelButtonStyle}>
              Cancel
            </button>
          )}
        </div>
      </form>

      {/* ================= CURRENT CANDIDATES ================= */}
      <h3 style={{ color: theme.text }}>Current Candidates</h3>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {candidates.length === 0 ? (
          <p style={{ color: theme.text }}>No candidates added yet.</p>
        ) : (
          candidates.map((c) => (
            <div
              key={c._id}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                padding: 10,
                backgroundColor: theme.card,
                borderRadius: 8,
              }}
            >
              <span style={{ display: "flex", alignItems: "center", gap: 10, color: theme.text }}>
                {c.image ? (
                  <img
                    src={c.image} // <-- backend URL, not File object
                    alt={`${c.firstName} ${c.lastName}`}
                    style={{ width: 40, height: 40, borderRadius: "50%", objectFit: "cover" }}
                  />
                ) : (
                  <div
                    style={{
                      width: 40,
                      height: 40,
                      borderRadius: "50%",
                      backgroundColor: "#ccc",
                    }}
                  />
                )}
                <div>
                  <strong>{c.firstName} {c.lastName}</strong> — {c.candidacy}
                  <br />
                  <small>{c.partylist || "Independent"}</small>
                </div>
              </span>

              <div style={{ display: "flex", gap: 8 }}>
                <button
                  onClick={() => handleEditClick(c)}
                  style={{
                    background: "#6366f1",
                    color: "#fff",
                    border: "none",
                    padding: "4px 10px",
                    borderRadius: 6,
                    cursor: "pointer",
                  }}
                >
                  Edit
                </button>
                <button
                  onClick={() => {
                    if (window.confirm("Delete this candidate?")) onDelete(c._id);
                  }}
                  style={{
                    background: "#ef4444",
                    color: "#fff",
                    border: "none",
                    padding: "4px 10px",
                    borderRadius: 6,
                    cursor: "pointer",
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* ================= VOTER CODES ================= */}
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <h3 style={{ color: theme.text }}>Voter Codes</h3>
        <button onClick={generateCodes} style={generateButtonStyle}>
          Generate Codes
        </button>
      </div>

      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={tableStyle}>Code</th>
            <th style={tableStyle}>Status</th>
            <th style={tableStyle}>Action</th>
          </tr>
        </thead>
        <tbody>
          {codes.map((c) => (
            <tr key={c._id}>
              <td style={tableStyle}>{c.code}</td>
              <td style={tableStyle}>{c.used ? "Used" : "Unused"}</td>
              <td style={tableStyle}>
                <button onClick={() => deleteCode(c._id)} style={deleteButtonStyle}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// ================= STYLES =================
const statCard = (theme) => ({
  background: theme.card || "#f1f5f9",
  padding: 15,
  borderRadius: 8,
  minWidth: 120,
  textAlign: "center",
});

const inputStyle = (theme) => ({
  padding: 8,
  borderRadius: 6,
  border: `1px solid ${theme.text}33`,
  width: "100%",
  backgroundColor: theme.background,
  color: theme.text,
});

const darkModeShadow = (theme) =>
  theme.background === "#1f1f2e"
    ? "0 2px 8px rgba(255,255,255,0.05)"
    : "0 2px 8px rgba(0,0,0,0.2)";

const buttonStyle = (theme) => ({
  padding: "8px 12px",
  borderRadius: 6,
  border: "none",
  backgroundColor: theme.button,
  color: theme.buttonText,
  cursor: "pointer",
  fontWeight: "bold",
});

const cancelButtonStyle = {
  padding: "8px 12px",
  borderRadius: 6,
  border: "none",
  backgroundColor: "#ef4444",
  color: "#fff",
  cursor: "pointer",
  fontWeight: "bold",
};

const deleteButtonStyle = {
  padding: "4px 8px",
  borderRadius: 6,
  border: "none",
  backgroundColor: "#ef4444",
  color: "#fff",
  cursor: "pointer",
};

const resetButtonStyle = {
  background: "#ef4444",
  color: "#fff",
  padding: "8px 12px",
  border: "none",
  borderRadius: 6,
  cursor: "pointer",
  width: 200,
};

const generateButtonStyle = {
  padding: "8px 14px",
  borderRadius: 6,
  border: "none",
  backgroundColor: "#22c55e",
  color: "#fff",
  cursor: "pointer",
  fontWeight: "bold",
};

const tableStyle = {
  border: "1px solid #ccc",
  padding: 8,
  textAlign: "center",
};

export default AdminPanel;
